-- Jobs + scholarships admin support
-- SAFE TO RUN MORE THAN ONCE. This script does NOT drop tables or delete/overwrite any rows:
--   * tables are created only if they do not exist
--   * columns are added only if missing
--   * policies are (re)created by name (policies hold no data)
--   * the 94 starter jobs are inserted with ON CONFLICT DO NOTHING,
--     so any job you already edited in the admin stays exactly as it is.
-- Generated by scripts/generate-jobs-sql.mjs

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Jobs
-- ---------------------------------------------------------------------------
create table if not exists public.jobs (
  id text primary key,
  title text not null,
  country text not null,
  region text not null default '',
  type text not null default 'unskilled',
  category text not null default '',
  salary text not null default '',
  positions integer not null default 1,
  experience text,
  education text,
  language text,
  visa_sponsorship boolean not null default true,
  accommodation_provided boolean not null default false,
  contract_duration text,
  employer text,
  description text,
  requirements jsonb not null default '[]'::jsonb,
  benefits jsonb not null default '[]'::jsonb,
  image_url text,
  featured boolean not null default false,
  status text not null default 'open',
  posted_date date default current_date,
  deadline date,
  is_published boolean not null default true,
  order_index integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- In case an older/partial jobs table already exists, make sure every column is present.
alter table public.jobs add column if not exists image_url text;
alter table public.jobs add column if not exists featured boolean not null default false;
alter table public.jobs add column if not exists is_published boolean not null default true;
alter table public.jobs add column if not exists order_index integer not null default 0;
alter table public.jobs add column if not exists requirements jsonb not null default '[]'::jsonb;
alter table public.jobs add column if not exists benefits jsonb not null default '[]'::jsonb;
alter table public.jobs add column if not exists updated_at timestamptz not null default now();

create index if not exists idx_jobs_country on public.jobs (country);
create index if not exists idx_jobs_published_order on public.jobs (is_published, order_index);
create index if not exists idx_jobs_status on public.jobs (status);

alter table public.jobs enable row level security;

drop policy if exists "jobs_public_read_published" on public.jobs;
create policy "jobs_public_read_published"
on public.jobs
for select
using (is_published = true or public.is_admin());

drop policy if exists "jobs_admin_all" on public.jobs;
create policy "jobs_admin_all"
on public.jobs
for all
using (public.is_admin())
with check (public.is_admin());

on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- Scholarships (table already exists in schema.sql; this only makes sure the
-- admin can manage it and the public can read it)
-- ---------------------------------------------------------------------------
create table if not exists public.scholarships (
  id uuid primary key default gen_random_uuid(),
  university text not null,
  name text not null,
  amount text,
  deadline date,
  eligibility text,
  apply_url text,
  created_at timestamptz not null default now()
);

alter table public.scholarships enable row level security;

drop policy if exists "scholarships_public_read" on public.scholarships;
create policy "scholarships_public_read"
on public.scholarships
for select
using (true);

drop policy if exists "scholarships_admin_all" on public.scholarships;
create policy "scholarships_admin_all"
on public.scholarships
for all
using (public.is_admin())
with check (public.is_admin());
